BEGIN;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('11db6acf-6c2f-5ecc-9733-ef95bea7c879', 'pretest', true, 1)
  ON CONFLICT (id) DO UPDATE SET current_version = GREATEST(item.current_version, EXCLUDED.current_version), updated_at = now();
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes)
VALUES ('11db6acf-6c2f-5ecc-9733-ef95bea7c879', 1, 'A 27-year-old Aboriginal woman presents to an Aboriginal Community Controlled Health Service in a remote town with 4 days of fever and painful, swollen knees and ankles. The pain has moved from joint to joint. She had a sore throat 3 weeks ago and has no previous history of acute rheumatic fever. Temperature is 38.3 °C and heart rate 108/min. A soft apical systolic murmur is heard. The clinic ECG shows a PR interval of 230 ms. Bloods including CRP have been sent to the regional laboratory, with results expected in 2 days. The visiting echocardiography service is next in town in 6 weeks. The nearest hospital with echocardiography is 400 km away, and the retrieval service can transfer her tomorrow.', 'What is the most appropriate next step?', '[{"id":"A","text":"Arrange transfer to hospital for assessment including echocardiography, using paracetamol for pain meanwhile"},{"id":"B","text":"Start naproxen for the arthritis and review her at the visiting echocardiography clinic in 6 weeks"},{"id":"C","text":"Give benzathine benzylpenicillin and enter her on the RHD register without further investigation"},{"id":"D","text":"Prescribe oral amoxicillin for 10 days and review her once the CRP result is available"}]'::jsonb, 'A', '{"A":"Correct. Australian guidance recommends that everyone with suspected ARF is admitted to hospital so the diagnosis can be confirmed and carditis assessed, particularly by early echocardiography. The echo result changes the diagnostic category, the severity of RHD and how long secondary prophylaxis lasts. Paracetamol is preferred for joint pain until the diagnosis is confirmed.","B":"Incorrect. Giving NSAIDs before the diagnosis is confirmed can suppress migratory polyarthritis and hide the evolving clinical picture. Waiting 6 weeks also delays assessment of carditis, education and register entry.","C":"Incorrect. A dose of benzathine benzylpenicillin to eradicate group A streptococcus is appropriate, but she still needs echocardiography and a confirmed diagnosis. Carditis severity determines her diagnostic category, RHD stage and how long she needs prophylaxis.","D":"Incorrect. Benzathine benzylpenicillin is the preferred eradication treatment because adherence to a 10-day oral course is unreliable. Waiting for the CRP also delays the admission she needs."}'::jsonb,
  'Admit all suspected ARF for confirmation of the diagnosis and echocardiography, and use paracetamol rather than NSAIDs for joint pain until the diagnosis is confirmed.', 'When echocardiography is weeks away, transfer is better than waiting. If transfer is delayed, start the workup locally (ECG, ESR/CRP, streptococcal serology, throat swab), give benzathine benzylpenicillin, discuss with the regional physician or RHD control program, and notify ARF as required by the jurisdiction.', 'Aboriginal and Torres Strait Islander Health', ARRAY['Adult Internal Medicine']::text[], ARRAY['D6','D8','D1']::text[],
  'acute rheumatic fever and RHD', 'remote', 'rural_adaptation', '{"age_band":"25-44","sex":"female","indigenous":true}'::jsonb, 3,
  'national', 'ai', NULL, '[{"source":"other","title":"The 2020 Australian guideline for prevention, diagnosis and management of acute rheumatic fever and rheumatic heart disease (3rd edition), RHDAustralia","locator":"Diagnosis of ARF; Management of ARF (hospitalisation, symptomatic treatment)","supports":"key"},{"source":"carpa","title":"CARPA Standard Treatment Manual","locator":"Acute rheumatic fever","supports":"key"}]'::jsonb,
  '', 'expert', ARRAY['Fixture reviewer']::text[], '2028-10-24', NULL)
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('0cbbeab0-bc9a-0e0c-8ec2-361582f2e770', 'pretest', true, 1)
  ON CONFLICT (id) DO UPDATE SET current_version = GREATEST(item.current_version, EXCLUDED.current_version), updated_at = now();
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes)
VALUES ('0cbbeab0-bc9a-0e0c-8ec2-361582f2e770', 1, 'A 22-year-old man is admitted to a rural hospital ward after a motorbike crash with a closed tibial fracture. He is awaiting transfer for fixation. He drinks about 16 standard drinks a day and his last drink was 30 hours ago. At 0200 the nurse calls you, the only doctor on call, with specialist advice available by phone. He is anxious and sweaty with a coarse tremor, but is orientated and not hallucinating. Heart rate is 118/min, blood pressure 156/94 mmHg and temperature 37.8 °C. Blood glucose is 6.2 mmol/L. His Alcohol Withdrawal Scale score is 16. He was given thiamine IV on admission. He has no head injury and no known liver or respiratory disease.', 'What is the most appropriate management now?', '[{"id":"A","text":"Haloperidol 5 mg IM and reassess in 1 hour"},{"id":"B","text":"Midazolam 5 mg IV then a midazolam infusion"},{"id":"C","text":"Diazepam 20 mg orally, repeated 2-hourly as needed"},{"id":"D","text":"Olanzapine 10 mg orally and observe hourly"}]'::jsonb, 'C', '{"A":"Incorrect. Antipsychotics do not treat alcohol withdrawal and lower the seizure threshold. Use them only as an adjunct for hallucinations or agitation that persist after adequate benzodiazepine treatment.","B":"Incorrect. A midazolam infusion needs high-dependency monitoring that a single on-call doctor on a rural ward cannot provide. It is unnecessary when he can take oral medicine.","C":"Correct. Moderate to severe withdrawal is treated with symptom-triggered oral diazepam, repeated about 2-hourly until symptoms are controlled, with regular reassessment and a maximum daily dose. Diazepam''s long-acting metabolites give a smooth, self-tapering effect and protect against seizures.","D":"Incorrect. Olanzapine does not prevent withdrawal seizures or delirium tremens, and like other antipsychotics it lowers the seizure threshold."}'::jsonb,
  'Benzodiazepines, usually oral diazepam given on a symptom-triggered schedule, are the treatment for alcohol withdrawal. Antipsychotics are adjuncts only.', 'With one doctor overnight, oral diazepam is safe and practical. Escalate (phone advice, transfer or retrieval) if large doses are needed, or if delirium, seizures or oversedation develop.', 'Addictive Behaviours', ARRAY[]::text[], ARRAY['D2','D3','D8']::text[],
  'alcohol withdrawal', 'ed', 'management', '{"age_band":"16-24","sex":"male","indigenous":false}'::jsonb, 3,
  'national', 'ai', NULL, '[{"source":"etg","title":"Therapeutic Guidelines: Addiction","locator":"Alcohol withdrawal syndrome management","supports":"key"},{"source":"other","title":"NSW Health Drug and Alcohol Withdrawal Clinical Practice Guidelines","locator":"Alcohol withdrawal: symptom-triggered diazepam","supports":"key"}]'::jsonb,
  '', 'expert', ARRAY['Fixture reviewer']::text[], '2028-10-24', NULL)
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('dde138d8-4270-05f6-ca2e-36117bcec85d', 'pretest', true, 1)
  ON CONFLICT (id) DO UPDATE SET current_version = GREATEST(item.current_version, EXCLUDED.current_version), updated_at = now();
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes)
VALUES ('dde138d8-4270-05f6-ca2e-36117bcec85d', 1, 'A 61-year-old man with severe COPD is admitted to the small hospital in a rural town of 3,000 people, 90 minutes by road from the nearest hospital with CT, with a 3-day exacerbation. He normally walks about 100 m on the flat. Since arriving on the ward 2 hours ago he has received oxygen at 8 L/min by Hudson mask. The nurse calls because he is now drowsy but rousable. Respiratory rate is 12/min, SpO2 99%, heart rate 104/min and blood pressure 138/82 mmHg. An arterial blood gas on the point-of-care analyser shows:
- pH 7.24
- PaCO2 82 mmHg
- PaO2 128 mmHg
- HCO3− 34 mmol/L', 'What is the best interpretation of this blood gas?', '[{"id":"A","text":"Chronic respiratory acidosis with full metabolic compensation"},{"id":"B","text":"Acute-on-chronic respiratory acidosis worsened by excess oxygen"},{"id":"C","text":"Acute respiratory acidosis with a coexisting metabolic acidosis"},{"id":"D","text":"Primary metabolic alkalosis with respiratory compensation"}]'::jsonb, 'B', '{"A":"Incorrect. A pH of 7.24 shows significant acidaemia, so the acidosis is not compensated. Chronic compensated hypercapnia has a near-normal pH.","B":"Correct. The raised bicarbonate shows chronic CO2 retention. It is higher than an acute rise alone would cause (about 28) but too low to compensate fully, so this is acute-on-chronic respiratory acidosis. High-flow oxygen with SpO2 99% and PaO2 128 mmHg has worsened hypercapnia and made him drowsy. Titrate oxygen to SpO2 88–92% and consider NIV.","C":"Incorrect. With a coexisting metabolic acidosis the bicarbonate would be lower than expected. Here it is raised.","D":"Incorrect. The patient is acidaemic. A primary metabolic alkalosis would give a raised pH."}'::jsonb,
  'In COPD with a raised bicarbonate and an acidaemic pH, recognise acute-on-chronic hypercapnic respiratory failure, often caused by excessive oxygen. Target SpO2 88–92%.', 'In a small hospital without ICU, titrate oxygen down promptly, start NIV if available and staff can monitor it, and arrange early retrieval if pH and drowsiness do not improve.', 'Adult Internal Medicine', ARRAY[]::text[], ARRAY['D3','D4','D1']::text[],
  'COPD exacerbation', 'ward', 'interpretation', '{"age_band":"45-64","sex":"male","indigenous":true}'::jsonb, 4,
  'national', 'ai', NULL, '[{"source":"other","title":"Lung Foundation Australia. COPD-X Plan: Australian and New Zealand Guidelines for the management of COPD","locator":"X: Manage exacerbations (oxygen therapy, NIV)","supports":"key"},{"source":"other","title":"TSANZ oxygen guidelines for acute oxygen use in adults: ''Swimming between the flags''","locator":"Target saturation in hypercapnic risk","supports":"key"}]'::jsonb,
  '', 'expert', ARRAY['Fixture reviewer']::text[], '2028-10-24', NULL)
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('1b3c137b-1177-4618-4e34-fa77ae7024ed', 'pretest', true, 1)
  ON CONFLICT (id) DO UPDATE SET current_version = GREATEST(item.current_version, EXCLUDED.current_version), updated_at = now();
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes)
VALUES ('1b3c137b-1177-4618-4e34-fa77ae7024ed', 1, 'A 72-year-old woman with metastatic lung cancer is admitted to a small hospital ward in a farming district of South Australia, 3 hours by road from a tertiary hospital. Overnight she develops pneumonia with worsening hypoxaemia and becomes too drowsy to make decisions. She has a valid Advance Care Directive, completed 6 months ago after her diagnosis, which states: ''I refuse intubation and mechanical ventilation in any circumstances. I want to be kept comfortable and I am happy to have antibiotics.'' Her son, who is appointed in the directive as her substitute decision-maker, arrives and insists she be transferred to the tertiary hospital for intensive care including ventilation. The retrieval service would accept her. She is receiving IV antibiotics and high-flow oxygen, which she tolerates.', 'What is the most appropriate course of action?', '[{"id":"A","text":"Arrange retrieval for intensive care because the substitute decision-maker requests it"},{"id":"B","text":"Continue ward care with antibiotics and comfort measures, without intubation"},{"id":"C","text":"Apply to SACAT and arrange retrieval for intubation while the matter is heard"},{"id":"D","text":"Intubate if she deteriorates, then review the directive once she is stable"}]'::jsonb, 'B', '{"A":"Incorrect. Under the Advance Care Directives Act 2013 (SA), a substitute decision-maker must act in line with the directive and cannot override a binding refusal of treatment. Transferring her for ventilation would act against her clearly expressed wishes.","B":"Correct. Her directive contains a clear, current refusal of intubation and mechanical ventilation that applies to this situation. In South Australia such a refusal is binding on health practitioners. Continue the care she has accepted (antibiotics, oxygen she tolerates, symptom control), explain the legal position compassionately to her son, and involve palliative care.","C":"Incorrect. SACAT can resolve genuine disputes or uncertainty, but the directive here is clear and applicable. Starting the refused treatment while an application is pending would breach the binding refusal.","D":"Incorrect. Intubating her against a known, applicable refusal is unlawful treatment. The directive must be considered before deterioration, not afterwards."}'::jsonb,
  'In South Australia, a clear refusal of treatment in a valid Advance Care Directive is binding and cannot be overridden by the substitute decision-maker. Provide the care the person has accepted.', 'Distance from ICU should never be the reason to withhold or provide treatment. Here the patient''s binding directive, not access, determines care, which allows her to stay close to home.', 'Aged Care', ARRAY['Palliative Care']::text[], ARRAY['D7','D2','D1']::text[],
  'advance care planning', 'ward', 'management', '{"age_band":"65-74","sex":"female","indigenous":false}'::jsonb, 5,
  'national', 'ai', NULL, '[{"source":"sa_health","title":"Advance Care Directives Act 2013 (SA) and SA Health Advance Care Directives policy and guidelines","locator":"Binding refusals of health care; role and limits of substitute decision-makers","supports":"key"}]'::jsonb,
  '', 'expert', ARRAY['Fixture reviewer']::text[], '2028-10-24', NULL)
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('1e39a54c-464a-8296-d67e-8ecfa9b576d7', 'pretest', true, 1)
  ON CONFLICT (id) DO UPDATE SET current_version = GREATEST(item.current_version, EXCLUDED.current_version), updated_at = now();
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes)
VALUES ('1e39a54c-464a-8296-d67e-8ecfa9b576d7', 1, 'A 58-year-old man is carried into a remote community clinic by family after being found on the floor at home. You are the visiting doctor on your weekly clinic day; RFDS retrieval has been requested and is at least 3 hours away. He smells of alcohol, has no external signs of head or facial injury, and his family report no fall from height. He has snoring, noisy respirations with a respiratory rate of 10/min and SpO2 88% on room air. Pulse is 92/min, BP 128/76 mmHg, GCS 9 (E2 V2 M5) and capillary glucose 6.1 mmol/L. When you gently suction his oropharynx he gags and coughs. Head tilt-chin lift improves the snoring, but it recurs whenever the manoeuvre is released.', 'What is the most appropriate next step in managing his airway?', '[{"id":"A","text":"Insert an oropharyngeal airway and apply oxygen"},{"id":"B","text":"Insert a nasopharyngeal airway and apply oxygen"},{"id":"C","text":"Insert a supraglottic airway and ventilate with a bag"},{"id":"D","text":"Perform rapid sequence induction and intubation"}]'::jsonb, 'B', '{"A":"An oropharyngeal airway is poorly tolerated when the gag reflex is present and can provoke vomiting and aspiration or laryngospasm.","B":"Correct. He has upper airway obstruction relieved by simple manoeuvres but an intact gag. A nasopharyngeal airway is tolerated with airway reflexes present, maintains patency without continuous manual support, and there are no features of base-of-skull or midface injury to contraindicate it. Supplemental oxygen corrects his hypoxaemia.","C":"A supraglottic airway requires absent airway reflexes; inserting one in a patient who gags risks vomiting, laryngospasm and aspiration. He is also breathing spontaneously and does not yet need ventilation.","D":"RSI is not the next step: his airway is maintainable with simple measures, and RSI in a remote clinic without anaesthetic support, monitoring and a team is high risk. It may become necessary if he deteriorates, ideally with the retrieval team."}'::jsonb,
  'In a patient with obstructed airway but an intact gag reflex and no base-of-skull injury, a nasopharyngeal airway plus oxygen is the appropriate adjunct after basic manoeuvres.', 'With retrieval hours away, choose the least invasive airway that works and reassess often; position him laterally if vomiting risk rises, and prepare (but do not rush) advanced airway skills for deterioration while seeking retrieval advice.', 'Anaesthetics', ARRAY['Emergency']::text[], ARRAY['D3','D4','D8']::text[],
  'airway management', 'ward', 'management', '{"age_band":"45-64","sex":"male","indigenous":false}'::jsonb, 2,
  'national', 'ai', NULL, '[{"source":"anzcor","title":"ANZCOR Guideline 4 - Airway","locator":"Airway opening manoeuvres and adjuncts","supports":"key"}]'::jsonb,
  '', 'expert', ARRAY['Fixture reviewer']::text[], '2028-10-24', NULL)
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('363f89c2-63bc-6601-9476-78f58c09786b', 'pretest', true, 1)
  ON CONFLICT (id) DO UPDATE SET current_version = GREATEST(item.current_version, EXCLUDED.current_version), updated_at = now();
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes)
VALUES ('363f89c2-63bc-6601-9476-78f58c09786b', 1, 'A 79-year-old man with severe COPD was admitted to a rural hospital ward this afternoon with an infective exacerbation. You are the only doctor on call overnight and are called at 0200 because he is more drowsy. Nursing staff increased his oxygen to 6 L/min via a simple face mask two hours ago when his SpO2 was 86%. He is now rousable to voice but drifts off mid-sentence. Respiratory rate is 14/min, SpO2 99%, pulse 104/min, BP 150/84 mmHg. An arterial blood gas on 6 L/min oxygen shows: pH 7.27, PaCO2 74 mmHg, PaO2 112 mmHg, HCO3- 33 mmol/L, base excess +6 mmol/L. A blood gas from his last admission three months ago showed pH 7.38, PaCO2 58 mmHg, HCO3- 33 mmol/L.', 'What is the best interpretation of tonight''s arterial blood gas?', '[{"id":"A","text":"Chronic compensated respiratory acidosis"},{"id":"B","text":"Primary metabolic alkalosis with respiratory compensation"},{"id":"C","text":"Acute respiratory acidosis with a metabolic acidosis"},{"id":"D","text":"Acute-on-chronic respiratory acidosis"}]'::jsonb, 'D', '{"A":"The pH of 7.27 is acidaemic and the PaCO2 has risen well above his known baseline of 58 mmHg. Chronic compensation would bring the pH close to normal, as on his previous gas.","B":"The raised bicarbonate is a chronic renal compensation for long-standing hypercapnia, not a primary process; a primary metabolic alkalosis would give an alkalaemic pH.","C":"There is no metabolic acidosis: bicarbonate and base excess are raised, not low.","D":"Correct. He has chronic hypercapnia with renal compensation (HCO3- 33) and a new acute rise in PaCO2 producing acidaemia. The PaO2 of 112 mmHg and SpO2 99% on 6 L/min suggest excessive oxygen is contributing; oxygen should be titrated to SpO2 88-92% and non-invasive ventilation considered."}'::jsonb,
  'In COPD, an acidaemic pH with a PaCO2 above the patient''s baseline and a raised bicarbonate indicates acute-on-chronic respiratory acidosis, often worsened by uncontrolled oxygen.', 'With one doctor on call, act on the gas immediately: reduce oxygen to target SpO2 88-92% via Venturi mask, start NIV if available and pH stays below 7.35, and discuss with the regional respiratory or ICU team early about transfer.', 'Chronic Disease', ARRAY['Emergency']::text[], ARRAY['D2','D3']::text[],
  'COPD', 'remote', 'interpretation', '{"age_band":"75-84","sex":"male","indigenous":false}'::jsonb, 2,
  'national', 'ai', NULL, '[{"source":"other","title":"COPD-X Plan: Australian and New Zealand Guidelines for the management of COPD (Lung Foundation Australia)","locator":"X: Manage eXacerbations - oxygen therapy and NIV","supports":"key"},{"source":"etg","title":"Therapeutic Guidelines: Respiratory","locator":"Acute exacerbation of COPD","supports":"key"}]'::jsonb,
  '', 'expert', ARRAY['Fixture reviewer']::text[], '2028-10-24', NULL)
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('aa311156-e055-af1c-252a-66d863243e53', 'pretest', true, 1)
  ON CONFLICT (id) DO UPDATE SET current_version = GREATEST(item.current_version, EXCLUDED.current_version), updated_at = now();
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes)
VALUES ('aa311156-e055-af1c-252a-66d863243e53', 1, 'A 32-year-old woman presents to a small rural hospital ED in southern New South Wales, 2 hours by road from the regional referral hospital. Three days ago she cut her shin on a submerged branch while wading in the Murray River. She now has a 15 cm area of spreading erythema, warmth and tenderness around the wound with a small amount of purulent discharge. Temperature is 38.6 degrees C, pulse 108/min, BP 118/72 mmHg. Pain is proportionate to the examination findings, there is no crepitus, bullae or skin necrosis, and she is alert. She has no drug allergies and no other medical history. You plan admission for IV antibiotics locally, with retrieval if she deteriorates.', 'What is the most appropriate empirical antibiotic therapy?', '[{"id":"A","text":"IV flucloxacillin alone"},{"id":"B","text":"IV cefazolin plus oral doxycycline"},{"id":"C","text":"IV cefazolin plus ciprofloxacin"},{"id":"D","text":"Oral amoxicillin with clavulanate"}]'::jsonb, 'C', '{"A":"Flucloxacillin covers Staphylococcus aureus and streptococci but not Aeromonas species, which are important pathogens in freshwater-associated wound infection.","B":"Doxycycline is added for seawater or brackish-water exposure to cover Vibrio species; it is not the recommended agent for freshwater exposure.","C":"Correct. For a moderate to severe skin infection after freshwater exposure, therapeutic guidelines recommend adding ciprofloxacin to an antistaphylococcal agent such as cefazolin to cover Aeromonas species.","D":"She is systemically unwell and warrants IV therapy; amoxicillin with clavulanate does not reliably cover Aeromonas."}'::jsonb,
  'Cellulitis after a freshwater wound needs empirical cover for Aeromonas (add ciprofloxacin), whereas seawater exposure needs cover for Vibrio (add doxycycline).', 'She can be managed locally with IV antibiotics, but set clear triggers for retrieval (haemodynamic instability, pain out of proportion, rapid spread) because necrotising infection needs surgical care that a small hospital cannot provide. In tropical northern Australia, also consider Burkholderia pseudomallei and follow regional guidance.', 'Dermatology', ARRAY['Emergency']::text[], ARRAY['D2','D3','D8']::text[],
  'cellulitis', 'retrieval', 'management', '{"age_band":"25-44","sex":"female","indigenous":false}'::jsonb, 3,
  'national', 'ai', NULL, '[{"source":"etg","title":"Therapeutic Guidelines: Antibiotic","locator":"Skin and soft tissue infections - water-related infections","supports":"key"}]'::jsonb,
  '', 'expert', ARRAY['Fixture reviewer']::text[], '2028-10-24', NULL)
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('215c1c0b-a334-0d96-7fe9-da2007124b2f', 'pretest', true, 1)
  ON CONFLICT (id) DO UPDATE SET current_version = GREATEST(item.current_version, EXCLUDED.current_version), updated_at = now();
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes)
VALUES ('215c1c0b-a334-0d96-7fe9-da2007124b2f', 1, 'A 56-year-old woman with chronic low back pain has been prescribed tapentadol modified release 100 mg twice daily by you for 18 months at a rural general practice in a town of 3,000 people. She attends requesting her next electronic prescription a week earlier than expected, saying she has been in more pain. Before prescribing, you check the state real-time prescription monitoring system. It shows that over the past 3 months she has also been dispensed oxycodone immediate release on four occasions, prescribed by two different doctors in a regional town 90 minutes away. She has never mentioned these prescriptions to you, and there are no red flag features for her back pain.', 'What is the most appropriate next step?', '[{"id":"A","text":"Discuss the monitoring findings openly and agree a single-prescriber plan"},{"id":"B","text":"Decline further opioid prescriptions and end your care of her"},{"id":"C","text":"Issue the prescription as requested and recheck the system next month"},{"id":"D","text":"Report her to police for obtaining opioids from multiple prescribers"}]'::jsonb, 'A', '{"A":"Correct. Real-time prescription monitoring is intended to support safer clinical decisions, not to punish. Discuss the findings non-judgementally, assess for opioid use disorder, overdose risk and uncontrolled pain, avoid early supply, and agree a plan with one prescriber and one pharmacy, seeking advice from the state drugs of dependence unit or addiction medicine service as needed.","B":"Abruptly stopping opioids and discharging her risks withdrawal, illicit opioid use and overdose, and abandons a patient who may need treatment for opioid use disorder.","C":"Prescribing early while ignoring concurrent opioid supply increases her overdose risk and fails to act on information the system was designed to provide.","D":"Monitoring information is used for clinical care; reporting to police is not an appropriate first response and would breach confidentiality without a lawful basis."}'::jsonb,
  'When real-time prescription monitoring reveals undisclosed opioid supply, discuss it openly, assess risk and agree a single-prescriber, single-pharmacy plan rather than punishing or ignoring it.', 'In a small town, the local pharmacist is a key partner in a single-pharmacy plan, and telehealth addiction medicine advice or opioid treatment programs may be the only specialist support available.', 'Digital Health', ARRAY[]::text[], ARRAY['D7','D2']::text[],
  'digital prescribing', 'clinic', 'management', '{"age_band":"45-64","sex":"female","indigenous":false}'::jsonb, 3,
  'national', 'ai', NULL, '[{"source":"red_book","title":"RACGP Prescribing drugs of dependence in general practice, Part C1: Opioids","locator":"Managing aberrant behaviours; prescription monitoring","supports":"key"},{"source":"sa_health","title":"ScriptCheckSA - information for prescribers","locator":"Responding to monitoring alerts","supports":"key"}]'::jsonb,
  '', 'expert', ARRAY['Fixture reviewer']::text[], '2028-10-24', NULL)
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('42850da8-f837-5d93-4499-e3afa18d58b8', 'pretest', true, 1)
  ON CONFLICT (id) DO UPDATE SET current_version = GREATEST(item.current_version, EXCLUDED.current_version), updated_at = now();
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes)
VALUES ('42850da8-f837-5d93-4499-e3afa18d58b8', 1, 'A 61-year-old man with COPD who smokes 30 cigarettes a day presents to a remote community clinic with sudden right-sided chest pain and breathlessness that began 6 hours ago. You are the visiting doctor on your weekly clinic day; the clinic has no X-ray. RR is 26/min, SpO2 89% on room air rising to 93% on 4 L/min nasal oxygen, pulse 108/min, BP 136/82 mmHg, and the trachea is midline. Breath sounds are reduced on the right. Point-of-care ultrasound shows absent lung sliding on the right with a lung point in the mid-axillary line. The clinic stocks 12 Fr Seldinger chest drain kits and one-way flutter valves, but no underwater-seal drainage system. RFDS will arrive in 90 minutes for a 2-hour flight to the regional hospital.', 'What is the most appropriate management before the flight?', '[{"id":"A","text":"Insert a small-bore Seldinger chest drain attached to a one-way flutter valve"},{"id":"B","text":"Give oxygen and request a sea-level cabin altitude, without inserting a drain"},{"id":"C","text":"Perform needle decompression in the second intercostal space, midclavicular line"},{"id":"D","text":"Insert a large-bore intercostal catheter by blunt dissection and clamp it for the flight"}]'::jsonb, 'A', '{"A":"Correct. This is a symptomatic secondary spontaneous pneumothorax in a patient with COPD, and current guidelines recommend a small-bore chest drain. Before air transport, a drain with a one-way flutter valve stops the pneumothorax from enlarging, works without an underwater seal, and is practical in an aircraft.","B":"A sea-level cabin limits gas expansion, but it does not treat a hypoxic, symptomatic secondary pneumothorax in a patient with little respiratory reserve. Flying with an undrained pneumothorax risks it enlarging, and tension, where it cannot be managed.","C":"Needle decompression is for tension pneumothorax. He is haemodynamically stable with a midline trachea. It is not definitive drainage and often fails or kinks.","D":"Clamping a chest drain for transport defeats its purpose and can cause tension pneumothorax. A large-bore drain is also unnecessary for a non-traumatic pneumothorax."}'::jsonb,
  'A symptomatic secondary spontaneous pneumothorax needs small-bore chest drainage before air transport, and the drain should never be clamped.', 'Ultrasound with a lung point can confirm pneumothorax when no X-ray is available. A flutter valve suits retrieval because it needs no underwater seal or suction. Secure the drain well and tell the RFDS team.', 'Emergency', ARRAY['Procedural Skills','Remote Medicine','Chronic Disease']::text[], ARRAY['D4','D8']::text[],
  'acute shortness of breath', 'retrieval', 'management', '{"age_band":"45-64","sex":"male","indigenous":false}'::jsonb, 3,
  'national', 'ai', NULL, '[{"source":"other","title":"BTS Guideline for pleural disease (2023)","locator":"Management of secondary spontaneous pneumothorax","supports":"key"},{"source":"other","title":"TSANZ position on spontaneous pneumothorax management","locator":"Secondary spontaneous pneumothorax - drainage","supports":"key"}]'::jsonb,
  '', 'expert', ARRAY['Fixture reviewer']::text[], '2028-10-24', NULL)
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('717f5eed-087e-e17b-880e-180b206a985a', 'pretest', true, 1)
