INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes)
VALUES ('717f5eed-087e-e17b-880e-180b206a985a', 1, 'A 20-year-old man attends the GP clinic attached to a small rural hospital, 2 hours by road from the regional referral centre. His partner, aged 21, is 8 weeks pregnant with their first child. She had reproductive carrier screening at her first antenatal visit and was found to be a carrier of a pathogenic CFTR variant (F508del). Her results for spinal muscular atrophy and fragile X syndrome were normal. Neither of them has a family history of cystic fibrosis, and he is well. He asks whether there is anything he needs to do.', 'What is the most appropriate next step?', '[{"id":"A","text":"Reassure him that newborn screening will detect cystic fibrosis after birth"},{"id":"B","text":"Arrange chorionic villus sampling for his partner at 11–13 weeks"},{"id":"C","text":"Reassure him that with no family history his risk is negligible"},{"id":"D","text":"Offer him cystic fibrosis carrier testing as soon as possible"}]'::jsonb, 'D', '{"A":"Newborn screening detects affected infants but removes the couple''s opportunity for informed reproductive choice during this pregnancy.","B":"Invasive prenatal testing carries a small miscarriage risk and is only indicated if both partners are carriers (a 1 in 4 risk of an affected fetus).","C":"About 1 in 25 people of European ancestry carry a CF variant, most with no family history, so his risk cannot be dismissed.","D":"Correct. When one partner is a carrier of an autosomal recessive condition, the reproductive partner should be offered prompt carrier testing (Medicare-funded). If he is also a carrier, the couple should be referred urgently for genetic counselling and offered prenatal diagnosis."}'::jsonb,
  'When one partner is found to carry an autosomal recessive variant, test the other partner promptly, before considering invasive prenatal diagnosis.', 'Partner testing is a blood or saliva sample that can be collected locally. Time matters because results take one to three weeks and CVS is offered at 11–13 weeks, so request testing the same day and arrange telehealth genetic counselling early.', 'Genetics', ARRAY['Obstetrics and Gynaecology']::text[], ARRAY['D2','D5']::text[],
  'carrier screening', 'clinic', 'management', '{"age_band":"16-24","sex":"male","indigenous":false}'::jsonb, 3,
  'national', 'ai', NULL, '[{"source":"other","title":"RANZCOG statement: Genetic carrier screening (C-Obs 63)","locator":"Partner testing and counselling","supports":"key"},{"source":"red_book","title":"RACGP Guidelines for preventive activities in general practice (Red Book)","locator":"Preconception and pregnancy care: genetic carrier screening","supports":"key"}]'::jsonb,
  '', 'expert', ARRAY['Fixture reviewer']::text[], '2028-10-24', NULL)
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('625d4dd2-dc14-f827-08c0-e4a24d455c71', 'pretest', true, 1)
  ON CONFLICT (id) DO UPDATE SET current_version = GREATEST(item.current_version, EXCLUDED.current_version), updated_at = now();
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes)
VALUES ('625d4dd2-dc14-f827-08c0-e4a24d455c71', 1, 'A 79-year-old man is brought by his daughter to the 6-bed emergency department of a small rural hospital, 2 hours by road from the regional referral hospital. He has dementia with Lewy bodies and mild parkinsonism, and has become acutely confused and agitated over 2 days with dysuria. Temperature is 38.1 °C, pulse 98/min, BP 132/76 mmHg. Urinalysis suggests infection and IV antibiotics have been started. Despite a quiet room, lighting adjustment, his daughter at the bedside and treatment of pain and urinary retention, he is repeatedly trying to pull out his cannula and has struck a nurse. With his daughter''s encouragement he will take tablets.', 'What is the most appropriate medication to manage his agitation?', '[{"id":"A","text":"Quetiapine 12.5 mg orally"},{"id":"B","text":"Haloperidol 0.5 mg orally"},{"id":"C","text":"Risperidone 0.5 mg orally"},{"id":"D","text":"Diazepam 10 mg orally"}]'::jsonb, 'A', '{"A":"Correct. In dementia with Lewy bodies and Parkinson disease, if an antipsychotic is unavoidable, low-dose quetiapine is preferred because it has the least dopamine D2 blockade among readily available options.","B":"Haloperidol is the usual choice for delirium-related agitation in older people, but patients with Lewy body dementia can have severe, sometimes fatal neuroleptic sensitivity reactions (rigidity, falls, reduced consciousness).","C":"Risperidone has substantial D2 blockade and also risks severe neuroleptic sensitivity and worsening parkinsonism in Lewy body dementia.","D":"Benzodiazepines can worsen delirium, cause paradoxical agitation and falls, and 10 mg of long-acting diazepam is excessive for a 79-year-old."}'::jsonb,
  'Avoid haloperidol and other potent D2 blockers in dementia with Lewy bodies or Parkinson disease; if medication is needed, use low-dose quetiapine.', 'With no geriatrician on site, check the drug choice by phone if unsure, document the indication and capacity or substitute decision-maker consent, and monitor closely, as an adverse reaction could require transfer.', 'Mental Health', ARRAY['Aged Care','Emergency']::text[], ARRAY['D2','D4']::text[],
  'agitated patient', 'ed', 'management', '{"age_band":"75-84","sex":"male","indigenous":false}'::jsonb, 5,
  'national', 'ai', NULL, '[{"source":"etg","title":"Therapeutic Guidelines: Psychotropic","locator":"Delirium; behavioural disturbance in patients with Parkinson disease or dementia with Lewy bodies","supports":"key"},{"source":"other","title":"Australian Commission on Safety and Quality in Health Care: Delirium Clinical Care Standard","locator":"Quality statement on use of antipsychotics","supports":"key"}]'::jsonb,
  '', 'expert', ARRAY['Fixture reviewer']::text[], '2028-10-24', NULL)
ON CONFLICT (item_id, version) DO NOTHING;
INSERT INTO item (id, status, calibration_core, current_version) VALUES ('d810c3f6-b829-62a8-8f03-6fbefcef9215', 'pretest', true, 1)
  ON CONFLICT (id) DO UPDATE SET current_version = GREATEST(item.current_version, EXCLUDED.current_version), updated_at = now();
INSERT INTO item_version (item_id, version, stem, lead_in, options, key, explanations, learning_point, rural_note,
  learning_area, secondary_areas, domains, presentation, context, cognitive_level, patient, target_difficulty,
  jurisdiction, provenance, generation, "references", tutor_context, review_level, reviewed_by, review_by, supersedes)
VALUES ('d810c3f6-b829-62a8-8f03-6fbefcef9215', 1, 'An 81-year-old man presents to the emergency department of a regional-town hospital at 9 pm with 3 weeks of worsening mid-thoracic back pain that is worse lying flat and wakes him at night. Over the past 2 days his legs have felt heavy and he has fallen twice. He was treated for metastatic prostate cancer 3 years ago. On examination he has tenderness over T8, power of 4/5 in both legs, brisk knee reflexes, and reduced sensation below the umbilicus. A bladder scan shows 650 mL of urine. Observations are normal. The nearest MRI and spinal surgical service are at the regional referral hospital 2 hours away.', 'What is the most appropriate next step?', '[{"id":"A","text":"Thoracic spine X-ray and review in clinic in the morning"},{"id":"B","text":"Simple analgesia, catheter, and physiotherapy assessment"},{"id":"C","text":"Non-urgent MRI referral and oncology letter this week"},{"id":"D","text":"Dexamethasone and urgent transfer for whole-spine MRI"}]'::jsonb, 'D', '{"A":"Plain films are insensitive for cord compression, and delay causes permanent neurological loss.","B":"A catheter is needed, but treating this as mechanical back pain ignores neurological signs of cord compression.","C":"Metastatic spinal cord compression is an emergency; outcome depends on neurological status at treatment, so non-urgent imaging is inappropriate.","D":"Correct. Known cancer, thoracic pain worse lying down, bilateral leg weakness, a sensory level and urinary retention indicate metastatic spinal cord compression. Give dexamethasone 16 mg (oral or IV) immediately and arrange same-day whole-spine MRI and oncology or spinal review."}'::jsonb,
  'Suspected metastatic spinal cord compression needs immediate dexamethasone and urgent whole-spine MRI.', 'When MRI is not local, start dexamethasone before transfer, keep the patient flat if spinal instability is suspected, and discuss with the receiving spinal and oncology teams so radiotherapy or surgery is not delayed.', 'Musculoskeletal', ARRAY['Emergency']::text[], ARRAY['D2','D4']::text[],
  'back pain', 'ed', 'management', '{"age_band":"75-84","sex":"male","indigenous":false}'::jsonb, 1,
  'national', 'ai', NULL, '[{"source":"other","title":"eviQ: Malignant spinal cord compression","locator":"Immediate management; corticosteroid dose","supports":"key"},{"source":"etg","title":"Therapeutic Guidelines: Palliative Care","locator":"Spinal cord compression","supports":"key"}]'::jsonb,
  '', 'expert', ARRAY['Fixture reviewer']::text[], '2028-10-24', NULL)
ON CONFLICT (item_id, version) DO NOTHING;
COMMIT;
